mapper.select:
SELECT id, wordbook_id AS wordbookId, JSON_UNQUOTE(JSON_EXTRACT(parsed_json, '$.title')) AS title, selected_terms_json AS selectedTermsJson, word_count_range AS wordCountRange, difficulty, study_status AS studyStatus, current_stage AS currentStage, practice_total AS practiceTotal, practice_correct AS practiceCorrect, practice_score AS practiceScore, create_time AS createTime, update_time AS updateTime FROM learning_article_study_record WHERE user_id = #{userId} AND deleted = 0
AND wordbook_id = #{wordbookId}
ORDER BY create_time DESC
